// --- web spatial puzzles (feat/web-puzzles-spatial) ---
// Crate Shift (box pushing) engine. Port of Android CrateShiftEngine.kt.
// Levels are generated by reverse-pulling boxes away from goals, then re-verified with a forward
// BFS solver (push-optimal), so every shipped level is provably solvable and non-trivial.
// Medium/Hard use longer reverse walks and lower push minimums than Android: with the Android values
// the generator almost always fell back to one fixed level.
// Grids have at most 64 cells; a box set is held as two int32 words (lo = cells 0-31, hi = 32-63).
import { makeRng } from './rng.js'

export const DR = [-1, 0, 1, 0]
export const DC = [0, 1, 0, -1]

function cfg(d) {
  switch (String(d).toLowerCase()) {
    case 'easy':
      return { w: 7, h: 6, boxes: 2, walls: 3, minPushes: 4, pullSteps: 90 }
    case 'hard':
      return { w: 8, h: 8, boxes: 4, walls: 9, minPushes: 9, pullSteps: 220 }
    default:
      return { w: 8, h: 7, boxes: 3, walls: 6, minPushes: 6, pullSteps: 300 }
  }
}

/** Neighbour index in direction d, or -1 if outside. */
export function step(w, h, idx, d) {
  const r = Math.floor(idx / w) + DR[d]
  const c = (idx % w) + DC[d]
  if (r < 0 || c < 0 || r >= h || c >= w) return -1
  return r * w + c
}

const has = (lo, hi, n) => (n < 32 ? (lo >>> n) & 1 : (hi >>> (n - 32)) & 1) === 1
const without = (lo, hi, n) => (n < 32 ? [lo & ~(1 << n), hi] : [lo, hi & ~(1 << (n - 32))])
const withBit = (lo, hi, n) => (n < 32 ? [lo | (1 << n), hi] : [lo, hi | (1 << (n - 32))])

function reach(w, h, walls, lo, hi, from) {
  const seen = new Uint8Array(w * h)
  const q = new Int32Array(w * h)
  let qh = 0
  let qt = 0
  q[qt++] = from
  seen[from] = 1
  while (qh < qt) {
    const cur = q[qh++]
    for (let d = 0; d < 4; d++) {
      const n = step(w, h, cur, d)
      if (n < 0 || walls[n] || seen[n] || has(lo, hi, n)) continue
      seen[n] = 1
      q[qt++] = n
    }
  }
  return seen
}

function deadCorner(w, h, walls, goals, cell) {
  if (goals[cell]) return false
  const wall = (d) => {
    const n = step(w, h, cell, d)
    return n < 0 || !!walls[n]
  }
  return (wall(0) || wall(2)) && (wall(1) || wall(3))
}

function walkPath(w, h, walls, lo, hi, from, to) {
  if (from === to) return []
  const prev = new Int32Array(w * h).fill(-1)
  const prevDir = new Int32Array(w * h)
  const seen = new Uint8Array(w * h)
  const q = [from]
  let qh = 0
  seen[from] = 1
  while (qh < q.length) {
    const c = q[qh++]
    for (let d = 0; d < 4; d++) {
      const n = step(w, h, c, d)
      if (n < 0 || walls[n] || seen[n] || has(lo, hi, n)) continue
      seen[n] = 1
      prev[n] = c
      prevDir[n] = d
      if (n === to) {
        const out = []
        let x = to
        while (x !== from) {
          out.push(prevDir[x])
          x = prev[x]
        }
        return out.reverse()
      }
      q.push(n)
    }
  }
  return null
}

export function solve(level, maxStates = 400000) {
  return solveFrom(level.w, level.h, level.walls, level.goals, level.boxes, level.player, maxStates)
}

/** Returns the full move list (directions 0..3: up,right,down,left) or null. `maxStates` caps search. */
export function solveFrom(w, h, walls, goals, boxes, player, maxStates = 400000) {
  let sLo = 0
  let sHi = 0
  let gLo = 0
  let gHi = 0
  for (let i = 0; i < boxes.length; i++) {
    if (boxes[i]) [sLo, sHi] = withBit(sLo, sHi, i)
    if (goals[i]) [gLo, gHi] = withBit(gLo, gHi, i)
  }
  if (sLo === gLo && sHi === gHi) return []

  const visited = new Set()
  const markSeen = (lo, hi, p) => {
    const k = `${lo},${hi},${p}`
    if (visited.has(k)) return true
    visited.add(k)
    return false
  }
  const region0 = reach(w, h, walls, sLo, sHi, player)
  markSeen(sLo, sHi, region0.indexOf(1))
  const queue = [{ lo: sLo, hi: sHi, player, parent: null, box: -1, dir: -1 }]
  let qh = 0
  let states = 0
  let goalNode = null
  search: while (qh < queue.length) {
    const node = queue[qh]
    queue[qh++] = null // free memory
    states++
    if (states > maxStates) return null
    const region = reach(w, h, walls, node.lo, node.hi, node.player)
    for (let b = 0; b < w * h; b++) {
      if (!has(node.lo, node.hi, b)) continue
      for (let d = 0; d < 4; d++) {
        const behind = step(w, h, b, (d + 2) % 4)
        const ahead = step(w, h, b, d)
        if (behind < 0 || ahead < 0 || !region[behind]) continue
        if (walls[ahead] || has(node.lo, node.hi, ahead)) continue
        if (deadCorner(w, h, walls, goals, ahead)) continue
        const [l1, h1] = without(node.lo, node.hi, b)
        const [nLo, nHi] = withBit(l1, h1, ahead)
        const reg2 = reach(w, h, walls, nLo, nHi, b)
        const norm = reg2.indexOf(1)
        if (markSeen(nLo, nHi, norm)) continue
        const child = { lo: nLo, hi: nHi, player: b, parent: node, box: b, dir: d }
        if (nLo === gLo && nHi === gHi) {
          goalNode = child
          break search
        }
        queue.push(child)
      }
    }
  }
  if (!goalNode) return null

  const pushes = []
  for (let cur = goalNode; cur && cur.parent; cur = cur.parent) pushes.push(cur)
  pushes.reverse()
  const moves = []
  let pos = player
  let lo = sLo
  let hi = sHi
  for (const pn of pushes) {
    const behind = step(w, h, pn.box, (pn.dir + 2) % 4)
    const walk = walkPath(w, h, walls, lo, hi, pos, behind)
    if (!walk) return null
    moves.push(...walk, pn.dir)
    pos = pn.box
    lo = pn.lo
    hi = pn.hi
  }
  return moves
}

function pushCount(w, h, boxes, player, moves) {
  const b = Array.from(boxes)
  let p = player
  let n = 0
  for (const d of moves) {
    const t = step(w, h, p, d)
    if (b[t]) {
      const a = step(w, h, t, d)
      b[t] = false
      b[a] = true
      n++
    }
    p = t
  }
  return n
}

function floorConnected(w, h, walls) {
  const first = walls.findIndex((x) => !x)
  if (first < 0) return false
  const seen = reach(w, h, walls, 0, 0, first)
  for (let i = 0; i < w * h; i++) if (!walls[i] && !seen[i]) return false
  return true
}

export function generate(difficulty, seed) {
  const c = cfg(difficulty)
  const rnd = makeRng(seed)
  for (let attempt = 0; attempt < 400; attempt++) {
    const { w, h } = c
    const walls = Array.from({ length: w * h }, (_, i) => {
      const r = Math.floor(i / w)
      const col = i % w
      return r === 0 || col === 0 || r === h - 1 || col === w - 1
    })
    let placed = 0
    let guard = 0
    while (placed < c.walls && guard++ < 200) {
      const i = rnd.nextInt(w * h)
      if (walls[i]) continue
      walls[i] = true
      if (floorConnected(w, h, walls)) placed++
      else walls[i] = false
    }
    const floor = []
    for (let i = 0; i < w * h; i++) if (!walls[i]) floor.push(i)
    rnd.shuffle(floor)
    const goalCells = floor.slice(0, c.boxes)
    const goals = new Array(w * h).fill(false)
    const boxes = new Array(w * h).fill(false)
    for (const g of goalCells) {
      goals[g] = true
      boxes[g] = true
    }
    let player = floor.find((i) => !boxes[i])
    for (let s = 0; s < c.pullSteps; s++) {
      const d = rnd.nextInt(4)
      const q = step(w, h, player, d)
      if (q < 0 || walls[q] || boxes[q]) continue
      const behind = step(w, h, player, (d + 2) % 4)
      if (behind >= 0 && boxes[behind] && rnd.nextDouble() < 0.75) {
        boxes[behind] = false
        boxes[player] = true
      }
      player = q
    }
    const sol = solveFrom(w, h, walls, goals, boxes, player, 150000)
    if (!sol) continue
    const pushes = pushCount(w, h, boxes, player, sol)
    if (pushes < c.minPushes) continue
    if (boxes.every((b, i) => b === goals[i])) continue
    return { w, h, walls, goals, boxes, player, par: sol.length, minPushes: pushes }
  }
  return fallback()
}

/** Hand-made 6x5 level used only if random generation fails. */
function fallback() {
  const w = 6
  const h = 5
  const walls = Array.from({ length: w * h }, (_, i) => {
    const r = Math.floor(i / w)
    const col = i % w
    return r === 0 || col === 0 || r === h - 1 || col === w - 1
  })
  const goals = new Array(w * h).fill(false)
  const boxes = new Array(w * h).fill(false)
  goals[1 * w + 4] = true
  boxes[2 * w + 2] = true
  const player = 2 * w + 1
  const sol = solveFrom(w, h, walls, goals, boxes, player)
  return { w, h, walls, goals, boxes, player, par: sol.length, minPushes: pushCount(w, h, boxes, player, sol) }
}

/** Play state with undo and move counting. */
export class CrateShiftState {
  constructor(level) {
    this.level = level
    this.w = level.w
    this.h = level.h
    this.hintsUsed = 0
    this.restart()
  }

  restart() {
    this.player = this.level.player
    this.boxes = this.level.boxes.slice()
    this.moves = 0
    this.pushes = 0
    this.undoStack = []
  }

  canUndo() {
    return this.undoStack.length > 0
  }

  solved() {
    for (let i = 0; i < this.boxes.length; i++) if (this.boxes[i] && !this.level.goals[i]) return false
    return true
  }

  /** Returns true if the move changed the state. */
  move(d) {
    const t = step(this.w, this.h, this.player, d)
    if (t < 0 || this.level.walls[t]) return false
    if (this.boxes[t]) {
      const a = step(this.w, this.h, t, d)
      if (a < 0 || this.level.walls[a] || this.boxes[a]) return false
      this.snapshot()
      this.boxes[t] = false
      this.boxes[a] = true
      this.pushes++
    } else this.snapshot()
    this.player = t
    this.moves++
    return true
  }

  snapshot() {
    const idx = []
    this.boxes.forEach((b, i) => b && idx.push(i))
    this.undoStack.push({ player: this.player, moves: this.moves, pushes: this.pushes, boxes: idx })
  }

  undo() {
    if (!this.undoStack.length) return false
    const s = this.undoStack.pop()
    this.player = s.player
    this.moves = s.moves
    this.pushes = s.pushes
    this.boxes.fill(false)
    for (const i of s.boxes) this.boxes[i] = true
    return true
  }

  /** A box is stuck in a corner off-goal: the level cannot be completed without undo. */
  deadlocked() {
    for (let i = 0; i < this.boxes.length; i++) {
      if (!this.boxes[i] || this.level.goals[i]) continue
      const wall = (d) => {
        const n = step(this.w, this.h, i, d)
        return n < 0 || !!this.level.walls[n]
      }
      if ((wall(0) || wall(2)) && (wall(1) || wall(3))) return true
    }
    return false
  }

  /** Next step toward a solution from the current position, or -1 if the solver cannot finish. */
  hint() {
    const sol = solveFrom(this.w, this.h, this.level.walls, this.level.goals, this.boxes, this.player, 200000)
    if (!sol || !sol.length) return -1
    this.hintsUsed++
    return sol[0]
  }

  stars() {
    const par = this.level.par
    return this.moves <= par + Math.floor(par / 4) ? 3 : this.moves <= par + Math.floor((par * 3) / 4) ? 2 : 1
  }

  score() {
    return 40 + this.stars() * 20
  }
}
